<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'new');if(in_array($status,['new','contacted','closed'],true)){$pdo->prepare('UPDATE estimate_requests SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Request status updated.');}header('Location: estimates.php?view='.$id);exit;}$rows=$pdo->query('SELECT * FROM estimate_requests ORDER BY id DESC')->fetchAll();$view=null;$atts=[];if(isset($_GET['view'])){$s=$pdo->prepare('SELECT * FROM estimate_requests WHERE id=?');$s->execute([(int)$_GET['view']]);$view=$s->fetch();if($view){$a=$pdo->prepare('SELECT * FROM estimate_attachments WHERE estimate_id=? ORDER BY id');$a->execute([$view['id']]);$atts=$a->fetchAll();}}$pageTitle='Estimate Requests';$active='estimates';require __DIR__.'/_header.php';?>
<div class="page-heading"><div><p class="eyebrow">FREE ESTIMATES</p><h1>Customer requests</h1><p class="muted">Every request submitted from the public website is stored here, even if email delivery is unavailable.</p></div></div>
<?php if($view):?><section class="panel animate-in"><div class="section-heading"><div><p class="eyebrow">REQUEST #<?=$view['id']?></p><h2><?=h($view['full_name']?:'Website visitor')?></h2></div><span class="badge <?=h($view['status'])?>"><?=h($view['status'])?></span></div><div class="three-col"><div class="list-card"><small>PHONE</small><strong><?=h($view['phone']?:'Not provided')?></strong></div><div class="list-card"><small>EMAIL</small><strong><?=h($view['email']?:'Not provided')?></strong></div><div class="list-card"><small>DESIRED DATE</small><strong><?=h($view['desired_date']?:'Not specified')?></strong></div></div><div class="two-col" style="margin-top:14px"><div class="list-card"><small>SERVICE</small><strong><?=h($view['service_needed']?:'General project')?></strong><p><?=h($view['address']?:'No address provided')?></p></div><div class="list-card"><small>PROJECT DETAILS</small><p><?=nl2br(h($view['message']?:'No additional details.'))?></p></div></div><?php if($atts||$view['photo_path']):?><div class="section-heading" style="margin-top:20px"><div><h2>Attached images</h2></div></div><div class="gallery-editor"><?php $all=$atts;if(!$atts&&$view['photo_path'])$all=[['file_path'=>$view['photo_path'],'original_name'=>'Project photo']];foreach($all as $a):?><article class="gallery-item"><div class="gallery-media"><img src="../<?=h($a['file_path'])?>" alt="Attachment"><button type="button" class="zoom-btn" data-preview-src="../<?=h($a['file_path'])?>" data-preview-caption="<?=h($a['original_name']??'Project image')?>"><?=icon('eye')?></button></div><footer><small><?=h($a['original_name']??'Project image')?></small></footer></article><?php endforeach;?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=$view['id']?>"><div class="form-actions"><select name="status" style="max-width:220px"><option value="new" <?=$view['status']==='new'?'selected':''?>>New</option><option value="contacted" <?=$view['status']==='contacted'?'selected':''?>>Contacted</option><option value="closed" <?=$view['status']==='closed'?'selected':''?>>Closed</option></select><button>Update status</button><a class="button secondary" href="estimates.php">Back to requests</a></div></form></section><?php endif;?>
<div class="request-grid"><?php foreach($rows as $r):?><article class="request-card animate-in"><div class="request-top"><div><strong><?=h($r['full_name']?:'Website visitor')?></strong><small><?=h($r['created_at'])?></small></div><span class="badge <?=h($r['status'])?>"><?=h($r['status'])?></span></div><p><strong><?=h($r['service_needed']?:'General project')?></strong><br><?=h($r['phone']?:$r['email']?:'No contact provided')?></p><div class="actions"><a class="button secondary small" href="?view=<?=$r['id']?>">Open request</a></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="empty-state"><strong>No estimate requests yet</strong><p>The public form is connected to this module.</p></div><?php endif;?><?php require __DIR__.'/_footer.php';